// ライノくんFAQリンク
.raino-faq {
    @include tab {
        position: unset;
        z-index: 2000;
    }
    .raino-faq-title {
        font-size: 1rem;
        color:#014E35;
        letter-spacing: .2rem;
        @include sp-wide {
            text-align: left;
            height: 100%;
            padding-top: .2rem;
        }
    }
    .raino-faq-subtitle {
        font-size: 1rem;
        margin: .5rem 0 .3rem;
        border-left: solid 5px #a7c53c;
        padding-left: 0.5rem;
    }
    &__content {
        background-color: #FFFDE7;
        margin-left: .5rem;
        border-radius: 5px;
        border: solid 2px #A7C53C;
        @include sp-wide {
            width: 7rem;
            height: 100%;
        }
        #js-raino-faq-open {
            @include sp-wide {
                width: 100%;
                position: relative;
                height: 100%;
            }
        }
        &__image {
            width: 80px;
            margin-left: auto;
            @include sp-wide {
                width: 40px;
                position: absolute;
                bottom: 0;
                right: 0;
            }
        }
        &__link {
            position: relative;
            &__image {
                position: absolute;
                @include pc {
                    height: 8rem;
                }
                @include sp-wide {
                    height: 6.5rem;
                    bottom: -7rem;
                    width: 35vh;
                    left: -2rem;
                    padding-left: 3.5rem;
                }
                @include sp-slim-max {
                    width: 40vh;
                }
                img {
                    position: relative;
                    bottom: .25rem;
                    width: 100%;
                    @include sp-wide {
                        bottom: 0rem;
                    }
                }
                &__raino-text {
                    img {
                        position: relative;
                        right: -3px;
                        top: 0;
                    }
                }
            }
        }
        &.closed {
            position: fixed;
            width: 100px;
            bottom: 5rem;
            right: 0;
            transform: translate(120px, -10px);
            transition: 1s;
            @include tab {
                width: 78px;
                transform: translate(0, 0);
                bottom: 5rem;
            }
            @include sp-minimun {
                width: 60px;
                bottom: 2rem;
            }
            &.active {
                transform: translate(0, 0);
            }
        }
    }
    &__search {
        right: -100%;
        z-index: 5;
        background-color: #fffde7;
        width: 440px;
        box-shadow: 0 .125rem .25rem rgba(0,0,0,.075);
        transition: .6s;
        top: 0 !important;
        @include sp-wide {
            width: 100%;
            right: 0;
            top: -350% !important;
            z-index: 1002;
            box-shadow: none;
        }
        &.active {
            right: 0;
            transition: .6s;
            @include sp-wide {
                top: 0% !important;
                z-index: 1002;
            }
        }
        #js-raino-faq-close {
            color: #009184;
            padding: .25rem 1rem;
            border: solid 1px #009184;
            border-radius: 50px;
            @include tab {
                font-size: 1.1rem;
                position: relative;
                top: .5rem;
            }
            i {
                font-size: 1.3rem;
                position: relative;
                top: .15rem;
                padding-left: .25rem;
                @include tab {
                    font-size: 1.5rem;
                }
            }
        }
        .search-submit {
            background-color: #a7c53c;
            color: #fff;
            position: absolute;
            top: 0;
            right: 0;
        }
        &__link {
            max-width: 230px;
        }
    }
}


/**********************************************
*　フォームリセット
***********************************************/
input.form-control{
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
    &:focus{
        box-shadow: none !important;
    }
}

/**********************************************
*　アニメーション
***********************************************/
@keyframes fadeout {
    0% {
        opacity: 1;
    }

    100% {
        opacity: 0;
    }
}
@keyframes fadein {
    0% {
        opacity: 0;
    }

    100% {
        opacity: 1;
    }
}
@keyframes disactiveslide {
    0% {
        width: 100%;
    }

    100% {
        width: 80%;
    }
}
@keyframes activeslide {
    0% {
        width: 80%;
    }

    100% {
        width: 100%;
    }
}
@-webkit-keyframes CircRot {
    from {
        -webkit-transform: rotate(0deg);
    }
    to {
        -webkit-transform: rotate(359deg);
    }
}
@keyframes CircRot {
    from {
        transform: rotate(0deg);
    }
    to {
        transform: rotate(359deg);
    }
}
/**********************************************
*　アコーディオン
***********************************************/
.acor-menu-child{
    display: none;
}
/**********************************************
*　ポップアップ
***********************************************/
.pop-up-child{
    display: none;
    animation: fadeout .3s ease 0s 1 forwards;
    &.opened{
        animation: fadein .3s ease 0s 1 forwards;
        display: block;
        position: fixed;
        z-index: 9999;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        height: auto;
        width: auto;
        background: rgba(0, 0, 0, 0.6);
    }
    .modal-child {
        border-radius: 15px;
        position: relative;
        z-index: 999;
        .close-modal {
            margin-bottom: .5rem;
            font-size: .95rem;
        }
        .btn-box {
            margin-bottom: 0 !important;
        }
    }
}

/**********************************************
*　新ポップアップ
***********************************************/
.overflow-hidden {
    overflow: hidden;
}

.modal_trigger, .plusa_modal_trigger{
  cursor: pointer;
  @include sp {
    -webkit-box-pack: justify;
    -ms-flex-pack: justify;
    justify-content: space-between;
    max-width: inherit;
  }
}

.modal_box, .plusa_modal_box {
  display: none;
  height: 100%;
  left: 0;
  position: fixed;
  top: 0;
  width: 100%;
  z-index: 10000;
}

.modal_bg {
  background-color: rgba(30, 30, 30, 0.65);
  height: 100%;
  width: 100%;
}

.modal_inner {
  background-color: #fff;
  padding: 3rem;
  position: absolute;
  width: 75%;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  margin: auto;
  max-height: 75%;
  @include tab {
    width: 85%;
    max-height: 85%;
  }
  @include sp {
    width: 90%;
    padding: 25px;
  }
}

.modal_block {
    max-height: calc(100% - 1.5rem);
    overflow-y: scroll;
    -ms-overflow-style: none;
    scrollbar-width: none;
    padding-bottom: 3rem;
    @include sp-wide {
        max-height: calc(100% - 2.5rem);
    }
    &::-webkit-scrollbar {
        display: none;
    }
    &::after {
        display: block;
        position: absolute;
        bottom: 3.5rem;
        left: 0;
        content: "";
        width: 100%;
        height: 60px;
        background: 
            -webkit-linear-gradient(top,
            rgba(255, 255, 255, 0) 0%,
            rgba(255, 255, 255, 0.9) 50%,
            rgba(255, 255, 255, 0.9) 50%,
            #fff 100%);
    }
    .btn-box {
        padding: 15px;
        background-color: #f8fcff;
        position: absolute;
        left: 0;
        right: 0;
        bottom: 0;
        margin: auto;
        text-align: center;
        z-index: 1;
        .link-btn {
            background-color: white;
            box-shadow: 0.5rem 1rem 1.5rem rgba(0, 0, 0, .15);
            @include sp-minimun {
                p {
                    padding-right: 1.5rem;
                }
            }
            .close-icon {
                display: block;
                position: absolute;
                width: 16px;
                height: 16px;
                right: 8px;
                top: 50%;
                transform: translateY(-50%);
                &::before, &::after {
                    content: "";
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    width: 2px;
                    height: 16px;
                    background-color: #8ec6e6;
                }
                &::before {
                    transform: translate(-50%, -50%) rotate(45deg);
                }
                &::after {
                    transform: translate(-50%, -50%) rotate(-45deg);
                }
            }
            &:hover {
                background-color: #92B0D0;
                .close-icon {
                    &::before, &::after {
                        background-color: white;
                    }
                }
            }
        }
        .modal_close {
            bottom: 0;
        }
        svg {
            width: 16% !important;
            right: 15px !important;
            max-width: 2rem;
        }
    }
}

.modal_close, .plusa-modal-close {
    cursor: pointer;
    position: absolute;
    left: 0;
    right: 0;
    margin: auto;
    bottom: 1.5rem;
    text-align: center;
    width: 20%;
    @include sp-wide {
        width: 50%;
    }
    @include sp {
        bottom: 25px;
    }
    & > div {
        color: white;
        background-color: #3E6187;
    }
    span {
        font-size: 1.6rem;
        line-height: 1;
        margin-top: 2.5rem;
        position: relative;
        top: 0.1rem;
    }
}

.modal_close {
    &.close-bth {
        left: auto;
        right: 1rem;
        top: 1rem;
        width: auto;
        color: #3e6187;
        @include sp-wide {
            right: 0.2rem;
            top: 0.2rem;
        }
        span {
            font-weight: bold;
            font-size: 2rem;
        }
    }
}

// カスタマイズ
.modal_box_new {
    position: fixed;
    width: 100%;
    height: 100%;
    z-index: 998;
    display: none;
    top: 0;
    @include tab {
        display: block;
        top: 100%;
        left: 0;
        transition: .5s;
        opacity: 1;
    }
    .modal_box_new_tit {
        width: 100%;
        padding: .25rem .5rem;
        margin-bottom: .5rem;
    }
    .modal_block_new {
        padding: 0 .5rem;
    }
    .modal_bg_new {
        background-color: rgba(30,30,30,.65);
        height: 100%;
        width: 100%;
        @include tab {
            background-color: transparent;
        }
    }
    .modal_close_new {
        width: 100px;
        cursor: pointer;
        color: #EA637B;
        font-weight: bold;
        text-align: center;
        font-size: .8rem;
        line-height: 1.9;
        border: 1px solid #EA637B;
        @include tab {
            position: static;
        }
    }
    &::after {
        content: "";
        width: 75%;
        height: 2rem;
        left: 50%;
        transform: translateX(-50%);
        bottom: 12.5%;
        border-radius: 0 0 6px 6px;
        display: block;
        position: absolute;
        background: -webkit-linear-gradient(top,rgba(255,255,255,0) 0%,rgba(255,255,255,.9) 50%,rgba(255,255,255,.9) 50%,#fff 100%);
        @include tab {
            width: 100%;
            bottom: 0;
            left: 0;
        }
    }
}
.modal_inner_new {
    position: absolute;
    top: 100px;
    bottom: 0;
    left: 0;
    right: 0;
    overflow-y: scroll;
    width: 75%;
    height: calc(75% - 80px);
    background-color: white;
    border-radius: 6px;
    padding: 1rem 1rem 2rem 1rem;
    margin: auto;
    @include tab {
        top: auto;
        width: 100%;
        height: auto;
        max-height: 80%;
        border-radius: 6px 6px 0 0;
    }
}
.js-modal_box_new-active {
    top: 0;
    display: block;
    .modal_bg_new {
        @include tab {
            background-color: rgba(30,30,30,.65);
            transition-duration: .5s;
            transition-delay: .5s;
        }
    }
}

// PCのみ 画面端に表示
.modal_box_new_side {
    @include sp-wide-min {
        pointer-events: none;
        &::after {
            width: calc(450px - 4px);
            height: 2rem;
            left: auto;
            right: calc(5% + 2px);
            transform: none;
            bottom: calc(5% + 2px);
        }
        .modal_bg_new {
            display: none;
        }
        .modal_inner_new {
            border: 2px solid #ea637b;
            width: 450px;
            height: auto;
            max-height: 220px;
            top: auto;
            bottom: 5%;
            left: auto;
            right: 5%;
            pointer-events: auto;
            padding: 0.5rem 1rem;
        }
        .modal_box_new_tit {
            padding: 0;
            margin-bottom: 0;
        }
    }
}

// スマホ用ログインモーダル
#login_modal_sp {
    pointer-events: none;
    @include sp-wide-min {
        display: none;
    }
    &.modal_box_new:after {
        content: none;
    }
    .modal_inner_new {
        pointer-events: auto;
        background-color: #FDF5E3;
        box-shadow: -3px -4px 4px 0px rgba(0,0,0,.1);
        display: flex;
