.link-btn {
    padding: 0 .25rem;
    position: relative;
    button {
        width: 100%;
        border-radius: 1rem;
        border-color: gainsboro;
        line-height: 1.7rem;
        margin-bottom: 0;
        letter-spacing: .1rem;
        display: -webkit-flex;
        display: -ms-flexbox;
        justify-content: space-between;
        -webkit-justify-content: space-between;
        -ms-flex-wrap: wrap;
        -webkit-flex-wrap: wrap;
        align-items: center;
        padding: .2rem .2rem .2rem .5rem;
        height: calc(100% - (0.5em * 2));
        &:before {
            width: 25px;
            height: 25px;
            -webkit-border-radius: 50%;
            border-radius: 50%;
            background: black;
            content: "";
            position: absolute;
            right: 10px;
            top: 50%;
            margin-top: -12px;
        }
        &:after {
            content: "";
            width: 10px;
            height: 10px;
            position: absolute;
            top: 50%;
            margin-top: 2px;
            right: 19px;
            border: 0px solid transparent;
            border-top: 2px solid #fff;
            border-right: 2px solid #fff;
            -webkit-transform: rotate(45deg);
            transform: rotate(45deg);
            border-radius: 2px;
        }
        p {
            position: relative;
            text-align: left;
            padding: .2rem 0 .2rem .5rem;
            font-size: 1rem;
            width: 100%;
            margin: 0;
            &::before {
                display: none;
            }
            &::after {
                display: none;
            }
        }
    }
}
