            margin-top: .5rem;
            @include pc-md {
                width: 100%;
            };
            .page-content-innerwrap {
                max-height: calc(100vh - 200px);
                overflow-y: auto;
                @include pc-md {
                    max-height: none;
                }
                @include sp-wide {
                    overflow-y: visible;
                    padding: 0;
                };
                @include sp {
                    display: -webkit-flex;
                    display: -ms-flexbox;
                    justify-content: space-between;
                    -webkit-justify-content: space-between;
                    -ms-flex-wrap: wrap;
                    -webkit-flex-wrap: wrap;
                    margin-bottom: 2rem;
                };
                @include pc-md {
                    overflow-y: visible;
                    padding: 0;
                    display: -webkit-flex;
                    display: -ms-flexbox;
                    justify-content: space-between;
                    -webkit-justify-content: space-between;
                    -ms-flex-wrap: wrap;
                    -webkit-flex-wrap: wrap;
                    margin-bottom: 2rem;
                };
                .link-btn {
                    width: 100%;
                    @include sp {
                        width: 49.5%;
                    };
                    button {
                        width: 100%;
                        border-radius: 1rem;
                        border-color: gainsboro;
                        line-height: 1.7rem;
                        margin: .5rem 0 0;
                        letter-spacing: .1rem;
                        height: auto;
                        @include pc-md {
                            min-height: 3rem;
                        }
                        @include sp-wide {
                            min-height: 2rem;
                        }
                        @include sp {
                            margin: 0 0 .5rem;
                        };
                        &::before {
                            display: none;
                        }
                        &::after {
                            display: none;
                        }
                        p {
                            text-align: left;
                            font-size: .9rem;
                            &:before {
                                display: block;
                            }
                            &:after {
                                content: "";
                                display: block;
                                width: 15px;
                                height: 15px;
                                position: absolute;
                                top: 60%;
                                transform: translate(0, -50%);
                                right: 10px;
                                margin: auto;
                                box-sizing: border-box;
                                border: 8px solid transparent;
                                border-top: 13px solid;
                                @include tab {
                                    top: 64%;
                                };
                            }
                        }
                        @include tab {
                            padding: .05rem .05rem .05rem .4rem !important;
                            border-radius: .8rem;
                        };
                    }
                    .pet-list-item {
                        background: #dbf1f8;
                        border: none;
                        border-radius: 50px;
                        p::after {
                            right: 16px;
                            border-top: 13px solid #5785b2;
                        }
                    }
                }
            }
            .side-top {
                position: absolute;
                top: 0 !important;
                bottom: auto !important;
            }
            .side-fixed {
                position: fixed;
                bottom: auto !important;
            }
            .side-bottom {
                top: auto !important;
                position: absolute;
                bottom: 80px !important;
            }
        }
        .flame-body {
            width: 75%;
            margin-top: .5rem;
            @include pc-md {
                width: 100%;
            };
        }
    }
}

// SPナビ ページトップ
.flame-side.sp-page-top {
