// SPナビ 画面下部
.flame-side.for-sp-nav{
    @include pc-md{
        .page-content-innerwrap{
            display: none !important;
        }
    }
    .sp-nav-btn{
        width: 70%;
        margin: 0 auto;
        background: rgba(0, 0, 0, 0.6);
        padding: 2%;
        border-radius: 10px 10px 0 0;
        position: fixed;
        bottom: 0;
        left: 50%;
        transform: translateX(-50%);
        -webkit-transform: translateX(-50%);
        -ms-transform: translateX(-50%);
        z-index: 100;
        color: white;
        display: none;
        @include pc-md {
            display: block;
        }
        span{
            position: relative;
            &:after{
                content: '';
                position: absolute;
                left: 1rem;
                top: 35%;
                width: 7px;
                height: 7px;
                border-top: 2px solid white;
                border-right: 2px solid white;
                -webkit-transform: rotate(45deg);
                transform: rotate(-45deg);
            }
        }
    }
    .sp-nav-close-btn {
        position: absolute;
        top: 1rem;
        right: 1rem;
        font-weight: 300;
        color: white;
        font-size: 1.5rem;
        display: none;
    }
    &.opened{
        position: fixed !important;
        bottom: 0;
        left: 0;
        width: 100% !important;
        background: rgba(0, 0, 0, 0.6);
        margin: 0 !important;
        padding: 4rem 2rem 5rem !important;
        overflow: scroll;
        z-index: 10001;
        height: 100vh;
        .sp-nav-close-btn {
            display: block;
        }
        .page-content-innerwrap{
            display: block !important;
            @include pc-md {
                display: flex !important;
            }
            .link-btn{
                width: 100% !important;
                @include pc-md {
                    width: 50% !important;
                }
                @include sp-wide {
                    width: 100% !important;
                }
                &.pet-list {
                    width: 100% !important;
                    &>a button{
                        @include pc-md {
                            border-radius: .8rem !important;
                            padding: 1rem .05rem 1rem .4rem !important;
                            margin-bottom: 1rem;
                        }
                        p {
                            @include pc-md {
                                font-size: 1.1rem;
                            }
                        }
                    }
                    .link-btn {
                        @include pc-md {
                            width: 48% !important;
                            margin-left: 1%;
                            margin-right: 1%;
                        }
                    }
                }
            }
        }
        @include sp{
            padding: 4rem 1rem 3rem;
        }
        .sp-nav-btn{
            display: none;
            span{
                top: 15%;
                transform: rotate(135deg);
            }
        }
    }
