/**********************************************
*　slick基本設定
***********************************************/
.slick-slider{
    position: relative;
    .slide-arrow.slick-arrow{
        position: absolute;
        top: 45%;
        &.prev-arrow{
            left: -3%;
            z-index: 1;
            transform: rotate(180deg);
            width: 7%;
            @include sp-wide {
                width: 10%;
                left: -6%;
            };
        }
        &.next-arrow{
            right: -3%;
            transform: rotate(360deg);
            width: 7%;
            @include sp-wide {
                width: 10%;
                right: -6%;
            };
        }
    }
    ul.slick-dots{
        padding: 0;
        li{
            &:only-child {
                display: none;
            }
            list-style: none;
            margin: auto 1%;
            button{
                font-size: 0;
                border: none;
                position: relative;
                background-color: transparent;
                &:before{
                    content: '●';
                    font-family: 'slick';
                    font-size: 6px;
                    line-height: 20px;
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    transform: translate(-50%, -50%);
                    width: 20px;
                    height: 20px;
                    text-align: center;
                    color: gray;
                }
            }
            &:hover{
                button{
                    &:before{
                        opacity: 0.6;
                    }
                }
            }
            &.slick-active{
                button{
                    &:before{
                        color: black;
                    }
                }
            }
        }
    }
}

