// 会員カード ポップアップ
.card-modal {
    display: none;
    position: relative;
    z-index: 1000;
    &__content {
        background: rgba(0,0,0,0.5);
        position: fixed;
        top: 0;
        bottom: 0;
        left: 0;
        right: 0;
        height: 100%;
        width: 100%;
        @include sp {
            overflow: auto;
        }
    }
    .mamber-card-detail {
        position: fixed;
        left: 50%;
        top: 50%;
        transform: translate(-50%, -50%);
        @include sp-wide {
            width: 100%;
        }
        &__content {
            width: 500px;
            height: auto;
            // height: 80vh;
            // max-height: 86%;
            max-height: 80vh;
            margin: auto;
            // position: fixed;
            // left: 50%;
            // top: 47%;
            // transform: translate(-50%, -50%);
            background-color: white;
            background-image: url(/cms/wp-content/themes/zenkosai/assets/images/common/card_bg.png);
            background-repeat: no-repeat;
            background-size: 62%;
            background-position: bottom right;
            border: solid 2px #0D0D0D;
            // overflow: auto; コンベンションが終了したらコメントアウト解除
            overflow: scroll; // コンベンションが終了したらコメントアウト
            @include sp-wide {
                width: 98%;
            }
            &__detail {
                .card-header {
                    display: -webkit-flex;
                    display: -ms-flexbox;
                    align-items: center;
                    justify-content: space-between;
                    -webkit-justify-content: space-between;
                    padding: 1rem 1.2rem !important;
                    background-color: #fff4e6;
                    border-bottom: 0;
                    position: fixed;
                    left: 0;
                    right: 0;
                    margin: auto;
                    width: 99%;
                    z-index: 1;
                    @include sp-wide {
                        width: 97%;
                    }
                    img {
                        width: 40%;
                    }
                    p {
                        color: #fa9834;
                        font-weight: bold;
                        font-size: 1.2rem;
                        letter-spacing: .1rem;
                        @include sp-wide {
                            font-size: 1.5rem;
                        }
                    }
                }
                .card-body {
                    display: -webkit-flex;
                    display: -ms-flexbox;
                    align-items: center;
                    justify-content: space-between;
                    -webkit-justify-content: space-between;
                    padding: 5rem 2rem 1rem !important;
                    min-height: 37vh;
                    @include pc {
                        min-height: 21vh;
                    }
                    @include tab {
                        min-height: 23vh;
                    }
