.top_slide_wrapper {
    @include sp-wide {
        padding-top: 1.5rem !important;
    }
    .top_slide_innerwrapper{
        max-width: 1000px; 
        margin: 0 auto;
        .top-slide-div {
            .slick-list {
                @include tab {
                    width: 600px;
                    transform: translateX(-60px);
                }
                @include sp-wide {
                    width: auto;
                    transform: translateX(0);
                    overflow: visible;
                }
            }
        }
        .top-slide-div,.csr-pickup-list{
            display: none;
            position: relative;
            width: 100%;
            overflow: hidden;
            &.slick-initialized {
                display: block;
            }
            .slick-list {
                overflow: visible;
                .slick-track{
                    display: flex;
                    -webkit-box-align: end;
                    -ms-flex-align: end;
                    align-items: flex-end;
                    @include tab {
                        margin-left: 0;
                        transform: translate3d(0, 0, 0);
                    }
                    @include sp-wide {
                        margin-left: auto;
                    }
                    .top-slide {
                        padding: 0 10px;
                        @include tab {
                            padding: 0 4px;
                        }
                        @include sp-wide {
                            padding: 0 5px;
                        }
                    }
                    .top-slide.slick-slide{
                        h2{
                            display: none;
                        }
                        &.slick-current.slick-active{
                            z-index: 100;
                            opacity: 1;
                            @include sp-wide{
                                position: relative;
                            };
                            h2{
                                background-color: white;
                                border-top: 1px solid;
                                border-bottom: 1px solid;
                                @include sp-wide{
                                    border-radius: 0;
                                    width: 95% !important;
                                    white-space: break-spaces !important;
                                    margin: 0 auto !important;
                                    text-align: center;
                                    color: white;
                                    &:after{
                                        content: "";
                                        position: absolute;
                                        top: 0;
                                        right: -3rem;
                                        width: 0;
                                        height: 0;
                                        border-style: solid;
                                        border-color: #6ba0d1 transparent transparent transparent;
                                        border-width: 3rem 3rem 0rem 0;
                                    }
                                }
                                width: 80%;
                                display: block;
                                text-align: center;
                                br{
                                    display: none;
                                }
                            }
                        }
                        .limit_startdate {
                            &__text {
                                opacity: 0;
                                transition: .4s;
                                @include sp-wide {
                                    opacity: 1;
                                }
                            }
                        }
                    }
                    .top-slide.slick-slide.slick-center{
                        .limit_startdate {
                            &__text {
                                opacity: 1;
                            }
                        }
                    }
                }
            }
            ul.top-slide-dots{
                justify-content: center;
                margin-top: 1rem;
                @include tab{
                    right: 75%;
                }
                @include sp-wide{
                    flex-direction: row;
                    position: unset;
                    margin-bottom: 0;
                    -webkit-box-align: end;
                    -ms-flex-align: end;
                    align-items: flex-end;
                    justify-content: center;
                    -webkit-justify-content: center;
                    margin-top: 0;
                }
                li:only-child{
                    display: none;
                }
                >li{
                    margin: 0 0.25rem;
                    list-style: none;
                    button{
                        padding: 0.25rem;
                        width: 10px;
                        height: 10px;
                        background-color: #D9D9D9;
                        font-size: 0;
                        border-radius: 50%;
                        @include sp-wide{
                            box-shadow: 1px 3px 1px rgba(112, 112, 112, 0.8);
                        }
                        &:focus {
                            box-shadow: 1px 3px 1px rgba(112, 112, 112, 0.8) !important;
                        }
                        &:before{
                            content: "";
                            font-size: 1rem;
                            position: absolute;
                            top: 50%;
                            right: 2%;
                            transform: translate(0, -50%);
                            color: black;
                            @include tab{
                                white-space: pre-wrap;
                                line-height: 1.5rem;
                                font-size: 1.2rem;
                            }
                            @include sp-wide{
                                right: 0;
                                width: 100%;
                                font-size: .9rem;
                                line-height: 1.3rem;
                            }
                        }
                    }
                    &.slick-active{
                        button{
                            padding: 0.25rem;
                            width: 10px;
                            height: 10px;
                            background-color: #B2B2B2;
                            font-size: 0;
                            border-radius: 50%;
                            &:before{
                                content: "";
                                font-size: 1.1rem;
                                position: absolute;
                                top: 50%;
                                right: 2%;
                                transform: translate(0, -50%);
                                color: white;
                                @include tab{
                                    white-space: pre-wrap;
                                    line-height: 1.5rem;
                                    font-size: 1.2rem;
                                }
                                @include sp-wide{
                                    right: 0;
                                    width: 100%;
                                    font-size: 1rem;
                                    line-height: 1.3rem;
                                    font-size: .9rem;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

