    .tab-wrap {
        display: flex;
        display: -webkit-flex;
        display: -ms-flexbox;
        flex-wrap: wrap;
        -ms-flex-wrap : wrap;
        -webkit-flex-wrap : wrap;
        margin: 20px 0 0;
        &:after {
            content: '';
            width: 100%;
            height: 3px;
            display: block;
            order: -1;
            background-color: #00583D;
        }
        &> input[type=radio] {
            display: none;
        }
    }
    .tab-label {
        color: #717171;
        background-color: #E8E8E8;
        font-weight: bold;
        white-space: nowrap;
        text-align: center;
        padding: .7% 2%;
        order: -1;
        position: relative;
        z-index: 1;
        cursor: pointer;
        flex: 1;
        text-align: left;
        border-radius: 0.5rem 0.5rem 0 0;
        flex-basis: calc((100% - 10px) / 3);
        flex-grow: inherit;
        max-width: calc((100% - 10px) / 3);
        white-space: normal;
        word-break: keep-all;
        @include sp-wide {
            padding: 2%;
        }
        &:not(:nth-of-type(3n)) {
            margin-right: 5px;
        }
    }
    .tab-content {
        width: 100%;
        height: 0;
        overflow: hidden;
        opacity: 0;
    }
    /* アクティブなタブ */
    .tab-switch {
        display: none;
        &:checked {
            &+.tab-label {
                background-color: #00583D;
                color: white;
                &+.tab-content {
                    height: auto;
                    opacity: 1;
                    transition: .5s opacity;
                    position: relative;
                    top: 4px;
                }
            }
        }
    }
    // タブのコンテンツが４つ以上の時
    .tab-wrap-more {
        margin-bottom: -5px;
        .tab-label {
            margin-top: 5px;
            @include tab {
                flex-basis: calc((100% - 5px) / 2);
                position: relative;
                max-width: calc((100% - 5px) / 2);
                margin-right: 0;
                &:not(:nth-of-type(2n)) {
                    margin-right: 5px;
                }
            }
        }
    }
