/**********************************************
*　サービス利用体験
***********************************************/
.report {
    margin: 1.5rem .5rem;
    width: calc(100% / 2 - 1rem);
    @include tab {
        width: 100%;
    };
    @include sp-wide {
        margin: 0 auto 1.5rem;
    }
    &-content {
        height: 100%;
        position: relative;
        box-shadow: 0 .1rem .5rem rgba(0,0,0,.10);
        @include sp-wide {
            height: auto;
            position: static;
            margin-bottom: .5rem;
        }
        &-txt {
            padding-bottom: 3rem;
            @include tab {
                padding-bottom: 5.5rem;
            }
            @include sp-wide {
                padding-bottom: 0rem;
                margin-bottom: .5rem;
            }
        }
    }
    .thoughts-txt {
        overflow: hidden;
        display: -webkit-box;
        text-overflow: ellipsis;
        -webkit-box-orient: vertical;
        -webkit-line-clamp: 3;
        max-height: calc(1em * 1.9 * 3);
        @include tab {
            max-height: calc(1em * 1.7 * 3);
        }
        p {
            text-align: left !important;
            margin-bottom: 0 !important;
        }
        span {
            font-size: 1rem !important;
            font-family: $font-family !important;
        }
    }
    &-imgbox{
        @include sp-wide {
            width: 25%;
            margin-right: 0 !important;
            margin-left: .5rem !important;
        }
        img{
            width: 75px;
            height: 75px;
            object-fit: contain;
            @include sp-wide {
                width: 50px;
                height: 50px;
            }
        }
    }
    &-iconbox {
        img {
            width: 10vw;
            height: 10vw;
            min-width: 75px;
            min-height: 75px;
            max-width: 100px;
            max-height: 100px;
        }
    }
    .photo_space_images {
        .glass_zoom {
            position: absolute;
            bottom: 0;
            right: 15px;
            background-color: cadetblue;
            color: white;
        }
        &+.modal_box {
            .modal_inner {
                padding: 4rem;
            }
            img {
                object-fit: contain;
                width: 100%;
                height: 100%;
            }
        }
        }
    .date-txt{
        font-size: small;
        border-bottom-color: #8DBF80;
    }
    &-txtbox{
        .cat-txt{
            font-size: small;
        }
        .service-txt{
            font-size: large;
        }
    }
    .service-user {
        font-size: small;
        border-radius: 0 0 .5rem .5rem;
        position: absolute;
        width: 100%;
        bottom: 0;
        @include sp-wide {
            position: static;
        }
        img {
            width: 40px;
        }
        &__icon {
            margin: 0 !important;
        }
    }
    &__lifesupport {
        .report-txtbox .cat-txt {
            color: #3E6242;
        }
        .service-user {
            background-color: #F4FAF0;
            .detail-txt {
                background-color: #3E6242;
            }
        }
    }
    &__csr {
        .report-txtbox .cat-txt {
            color: #3583BC;
        }
        .service-user {
            background-color: #F2FAFC;
            .detail-txt {
                background-color: #64B1EA;
            }
        }
    }
    .post-date-txt {
        font-size: small;
    }
