                                @include tab {
                                    width: 89%;
                                };
                                @include sp {
                                    width: 90%;
                                    padding-right: 2rem;
                                };
                            }
                        }
                        .acor-menu {
                            position: relative;
                            &:before {
                                width: 25px;
                                height: 25px;
                                -webkit-border-radius: 50%;
                                border-radius: 50%;
                                background: white;
                                content: "";
                                position: absolute;
                                right: 1%;
                                top: 50%;
                                margin-top: -12px;
                                @include sp {
                                    width: 20px;
                                    height: 20px;
                                };
                            }
                            &:after {
                                content: "";
                                width: 10px;
                                height: 10px;
                                position: absolute;
                                top: 38%;
                                right: .95rem;
                                border: 0px solid transparent;
                                border-top: 2px solid #707070;
                                border-left: 2px solid #707070;
                                -webkit-transform: rotate(-135deg);
                                transform: rotate(-135deg);
                                border-radius: 2px;
                                @include pc-wide {
                                    right: .85rem;
                                }
                                @include pc-md {
                                    right: .95rem;
                                }
                               @include tab {
                                    top: 34%;
                                    right: .85rem;
                                };
                                @include sp {
                                    top: .5rem;
                                    right: .55rem;
                                    width: 10px;
                                    height: 10px;
                                };
                                @include sp-minimun {
                                    top: 1.4rem;
                                }
                            }
                        }
                        .acor-menu.opened {
                            position: relative;
                            &:before {
                                margin-top: -12px;
                               @include sp {
                                    width: 20px;
                                    height: 20px;
                               };
                            }
                            &:after {
                                -webkit-transform: rotate(45deg);
                                transform: rotate(45deg);
                                margin-top: 3px;
                            }
                        }
                    }
                    .faq {
                        width: 95%;
                        margin: auto auto 0;
                        position: relative;
                        button {
                            padding: .3rem .5rem;
                            &:before,
                            &:after {
                                display: none;
                            }
                            p {
                                width: 100% !important;
                                &:before,
                                &:after {
                                    display: none;
                                }
                            }
                            .question {
                                display: -webkit-flex;
                                display: -ms-flexbox;
                                -ms-flex-wrap: wrap;
                                -webkit-flex-wrap: wrap;
                                align-items: center;
                                position: relative;
                                width: 100%;
                                padding: .3rem 0;
                                &__mark {
                                    color: black;
