    .stephead {
        display: flex;
        width: 100%;
        margin: 0 auto;
        padding: 0;
        list-style: none;
    }
    .stephead_content {
        box-sizing: border-box;
        position: relative;
        width: calc((100% - 30px) / 3);
        height: 80px;
        margin: 0 5px;
        padding: 1px;
        background: $darkgreen;
    }
    .stephead_content:nth-child(1) {
        z-index: 4;
    }
    .stephead_content:nth-child(2) {
        z-index: 3;
    }
    .stephead_content:nth-child(3) {
        z-index: 2;
    }
    .stephead_content:nth-child(4) {
        z-index: 1;
    }
    .stephead_content:first-child {
        margin-left: 0;
    }
    .stephead_content:last-child {
        margin-right: 0;
    }
    .stephead_content:not(:first-child)::before {
        position: absolute;
        content: "";
        top: 0;
        left: 1px;
        width: 0;
        height: 0;
        border-top: 40px solid transparent;
        border-right: 0;
        border-bottom: 40px solid transparent;
        border-left: 20px solid $darkgreen;
    }
    .stephead_content:not(:first-child)::after {
        position: absolute;
        content: "";
        top: 0;
        left: 0;
        width: 0;
        height: 0;
        border-top: 40px solid transparent;
        border-right: 0;
        border-bottom: 40px solid transparent;
        border-left: 20px solid #ffffff;
    }
    .stephead_content_item {
        display: flex;
        justify-content: center;
        align-items: center;
        width: 100%;
        height: 100%;
        background: #ffffff;
        font-size: 1rem;
        font-weight: bold;
        @include sp {
            font-size: 0.7rem;
        }
        p {
            @include sp {
                margin-left: 1.4rem !important;
            }
        }
    }
    .stephead_content_item--current {
        background: transparent;
        color: #ffffff;
    }
    .stephead_content:not(:last-child) .stephead_content_item::before {
        position: absolute;
        content: "";
        top: 0;
        left: 100%;
        width: 0;
        height: 0;
        border-top: 40px solid transparent;
        border-right: 0;
        border-bottom: 40px solid transparent;
        border-left: 20px solid $darkgreen;
    }
    .stephead_content:not(:last-child) .stephead_content_item::after {
        position: absolute;
        content: "";
        top: 0;
        left: calc(100% - 1px);
        width: 0;
        height: 0;
        border-top: 40px solid transparent;
        border-right: 0;
        border-bottom: 40px solid transparent;
        border-left: 20px solid #ffffff;
    }
    .stephead_content:not(:last-child) .stephead_content_item--current::after {
        display: none;
    }
