/**********************************************
*　オンラインセミナー動画
***********************************************/
.page-template-page-seminar-movie {
    background-color: #EFFBFC;
}
.page-seminar-movie {
    .page-header {
        @include sp-wide {
            padding-top: 2rem;
        }
    }
    .page-top {
        &__back {
            padding: 2rem 10%;
            min-height: 13rem;
            background-color: #A2C9F0;
            @include tab {
                min-height: 9.5rem;
            }
            @include sp {
                min-height: 7.5rem;
            }
        }
    }
    .page-content-wrapper {
        h2{
            position: relative;
            padding: 0 1rem;
            margin-bottom: 1rem;
            display: inline-block;
            z-index: 1;
            &.page-title{
                background: linear-gradient(transparent 95%, #98B6E6 70%);
                padding: .5rem 1rem;
                color: #0f2338;
                font-weight: bold;
                word-break: keep-all;
                margin-left: 7.5%;
                @include sp-wide{
                    font-size: 1.5rem;
                }
            }
        }
        .page-overview {
            margin: 0 auto;
            width: 85%;
        }
        .seminar-image-wrap{
            align-self: flex-end;
            &:last-of-type {
                .container-fluid {
                    .row {
                        margin-bottom: 0;
                    }
                }
            }
        }
        .container-fluid {
            padding: 0;
            .precautions {
                width: 85%;
                margin: 0 auto 3rem;
                padding: 1.5rem 2rem;
                background-size: auto auto;
                background-color: #466c92;
                h3 {
                    text-align: center;
                    font-size: 1.3rem;
                    margin-bottom: 1rem;
                    color: #fff;
                }
                p{
                    background: #fff;
                }
            }
            .instructors-list {
                width: 100%;
                padding: 2rem;
                background-color: #cadae8;
                h2{
                    @include sp-wide{
                        font-size: 1.2rem;
                    }
                }
                .page-content-innerwrap {
                    width: 90%;
                    margin: 0 auto;
                    .page-content-div {
                        display: -webkit-flex;
                        display: -ms-flexbox;
                        .page-content {
                            .instructors-list-btn-wrap{
                                background-color: #fff;
                                transition: .15s ease-out;
                                -webkit-transform: translateZ(0);
                                display: inline-block;
                                box-sizing: border-box;
                                border: 1px solid;
                                border-bottom: 4px solid;
                                border-color: #466c92;
                                border-radius: 3rem;
                                color: inherit;
                                text-align: center;
                                line-height: 1;
                                text-decoration: none;
                                width: 95%;
                                &:hover {
                                    background-color: #466c92;
                                    transform: translateY(2px);
                                    opacity: 1;
                                    border-bottom: 1px solid #466c92;
                                    button{
                                        opacity: 1;
                                        p{
                                            color: #fff;
                                        }
                                    }
                                    .fa-arrow-down:before{
                                        color: #fff;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    .container {
        .row {
            width: 100%;
            @include tab {
                width: auto;
            }
            .flame-side{
                @include pc-md{
                    display:none;
                    &.for-sp-nav{
                        display: block;
                    }
                }
            }
            .flame-body {
                & + .container {
                    @include tab {
                        display: block;
                    }
                }
                .instructors-movie {
                    .page-content-innerwrap {
                        h4 {
                            font-size: 1.2rem;
                            text-align: center;
                            background-color: #466c92;
                            width: 80%;
                            margin: 0 auto 1rem;
                            padding: 1rem;
                            border-radius: 50px;
                            font-weight: bold;
                            color: white;
                        }
                        .page-content-div {
                            .container-fluid {
                                .row {
                                    width: auto;
                                    margin-bottom: 3rem;
                                    .page-content {
                                        h5 {
                                            font-size: 1.1rem;
                                        }
                                    }
                                }
                            }
                        }
                        &:last-of-type {
                            .page-content-div {
                                .container-fluid {
                                    .row {
                                        margin-bottom: 0;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    .breadSection {
        .row {
            width: auto;
        }
    }
}

