.page-faq.page-wrapper.pc.user_loggedin {
    margin-top: 5.5rem;
    @include tab {
        margin-top: 8rem;
    }
}
// FAQ 共通パーツ
.faq-nextanswer {
    position: relative;
    padding: .5rem 2.5rem .5rem 1rem;
    border: solid 1px #c9c9c9;
    border-radius: 5px;
    color: black;
    &:before {
        width: 25px;
        height: 25px;
        -webkit-border-radius: 50%;
        border-radius: 50%;
        background-color: $faq-subcolor;
        content: "";
        position: absolute;
        right: 10px;
        top: 50%;
        margin-top: -12px;
    }
    &:after {
        content: "";
        width: 10px;
        height: 10px;
        position: absolute;
        top: 50%;
        margin-top: -4px;
        right: 19px;
        border: 0px solid transparent;
        border-top: 2px solid #fff;
        border-right: 2px solid #fff;
        -webkit-transform: rotate(45deg);
        transform: rotate(45deg);
        border-radius: 2px;
    }
    .faq-cat {
        color: gray;
        font-size: .9rem;
        @include tab {
            font-size: 1.5vw;
        }
        @include sp-wide {
            font-size: 3vw;
            padding-right: .5rem;
        }
    }
}
.faq-title {
    font-size: 1.5rem;
    margin-bottom: 0;
    border-bottom: solid 1px $faq-subcolor;
}
.search-faq {
    background-color: #F4F4F4;
    .columns {
        .page-content-innerwrap {
            .serch-item {
                display: -webkit-flex;
                display: -ms-flexbox;
                align-items: center;
                margin: .5rem;
                @include tab {
                    margin: 0 0 .5rem 0;
                    justify-content: space-between;    
                    -webkit-justify-content: space-between;
                }
                h2 {
                    font-size: 1.3rem;
                    margin-right: 1.5rem;
                    i {
                        padding-right: .5rem;
                    }
                }
                a {
                    font-size: .85rem !important;
                    padding: .3rem 1.5rem;
                    box-shadow: $back-shadow;
                }
            }
            .serch-item-sub {
                margin: 1rem .5rem .5rem;
                @include tab {
                    margin: 0 0 .5rem 0;
                }
                h3 {
                    font-size: 1.1rem;
                    margin-right: 1.5rem;
                    padding-left: .5rem;
                    border-bottom: 1px solid black;
                }
            }
            form {
                position: relative;
                margin: .5rem .5rem 1rem .5rem;
                width: 48.5%;
                @include tab {
                    margin: 0rem 0rem 1rem 0rem;
                    width: 100%;
                }
                .form-control {
                    padding: .25rem 6.5rem .25rem 1rem !important;
                    @include sp-minimun {
                        font-size: .7rem;
                        height: 33.5px;
                    }
                }
                button {
                    background-color: $faq-maincolor;
                    box-shadow: $back-shadow;
                    color: white;
                    position: absolute;
                    top: 0;
                    right: 0;
                }
            }
            section {
                div {
                    h3 {
                        font-size: 1.2rem;
                        font-weight: bold;
                    }
                    a {
                        font-size: .85rem !important;
                        padding: .3rem 1.5rem;
                        box-shadow: $back-shadow;
                        margin-top: -0.2rem;
                    }
                }
                ul {
                    list-style: none;
                    background-color: #f8f9da;
                    margin: .5rem 0 0;
                    padding: 1rem 1.5rem .5rem;
                    border-radius: 5px;
                    @include sp {
                        margin-top: 1rem;
                    }
                    li {
                        line-height: 1em;
                        a {
                            color: #005545;
                            &:hover {
                                color: #43c5ad;
                            }
                        }
                    }
                }
            }
            .faq-backlink {
                display: -webkit-flex;
                display: -ms-flexbox;
                -ms-flex-wrap : wrap;
                -webkit-flex-wrap : wrap;
                @include tab {
                    display: block;
                }
                a {
                    width: calc(100% / 2 - 1rem);
                    margin: .5rem;
                    padding: 0;
                    box-shadow: none;
                    &:hover {
                        opacity: .6;
                    }
                    .faq-nextanswer {
                        background-color: white;
                        border: none;
                        box-shadow: $back-shadow;
                    }
                }
                &__btn {
                    background-color: white;
                    padding: .5rem 2.5rem .5rem 1rem;
                    border: solid 1px #c9c9c9;
                    border-radius: 5px;
                    color: black;
                    &:hover {
                        color: #c9c9c9;
                    }
                }
            }
        }
    }
}
.search-faq.related-q {
    .columns {
        .page-content-innerwrap {
            .faq-backlink {
                a {
                    .faq-nextanswer {
                        &:before {
