// カテゴリーページ
#page-ufaq {
    .faq_breadcrumb_container {
        overflow-x: scroll;
        width: calc(100vw - 15px);
        padding-bottom: .5rem;
    }
    .breadSection {
        .breadcrumb {
            padding: 0;
            display: block;
            content: "";
            clear: both;
            &>li {
                float: left;
                background-color: #F5F5EF;
                padding: .5rem 1rem;
                position: relative;
                margin-right: 2rem;
                @include tab {
                    margin-right: 32px;
                }
                &::before {
                    content: "";
                    position: absolute;
                    top: 0;
                    left: -1.8rem;
                    border-right: 30px solid #F5F5EF;
                    border-top: 2.2rem solid transparent;
                    margin-left: 0;
                    margin-right: 0;
                    @include tab {
                        top: -1px;
                        left: -29px;
                    }
                }
                &::after {
                    content: "";
                    position: absolute;
                    top: 0;
                    right: -1.8rem;
                    border-left: 30px solid #F5F5EF;
                    border-bottom: 2.2rem solid transparent;
                    @include tab {
                        top: 0px;
                        right: -29px;
                    }
                }
                &:first-of-type {
                    &::before {
                        content: none;
                    }
                }
                &:last-of-type {
                    background-color: #E8E8CC;
                    &::before {
                        border-right: 30px solid #E8E8CC;
                    }
                    &::after {
                        border-left: 30px solid #E8E8CC;
                    }
                }
                a {
                    &:hover {
                        border-bottom: none;
                        opacity: .8;
                    }
                }
            }
        }
    }

    .page-content-wrapper {
        padding-top: 4rem;
        .flame-body {
            .page-content-innerwrap {
                width: 100%;
                .page-content-div {
                    .cat-description {
                        margin: 1rem 0 3rem;
                    }
                    .faq-cat-list {
                        padding: 0;
                        list-style: none;
                        display: -webkit-flex;
                        display: -ms-flexbox;
                        -ms-flex-wrap: wrap;
                        -webkit-flex-wrap: wrap;
                        @include tab {
                            display: block;
                        }
                        a {
                            color: black;
                            width: calc(100% / 2 - 1rem);
                            margin: .5rem;
                            li {
                                margin-bottom: 0;
                                height: 100%;
                                line-height: 1.4rem;
                                &:hover {
                                    opacity: .5;
                                }
                            }
                        }
                    }
                    // 回答ページ
                    .faq-answer {
                        &__explanation,
                        &__link,
                        &__detail {
                            margin: 0rem 2rem;
                        }
                        &__heading {
                            background-color: $faq-subcolor;
                            font-size: 1.2rem;
                            color: white;
                            border-radius: 50px;
                            margin-bottom: 1rem;
                            padding: .25rem 2rem;
                        }
                        &__explanation {
                            margin-bottom: 2rem;
                        }
                        &__link {
                            background-color: #F8F8F8;
                            margin-bottom: 1rem !important;
                            border-radius: 8px;
                            padding: 1rem;
                            &:last-child {
                                margin-bottom: 2rem !important;
                            }
                            &__title,
                            &__list {
                                padding: 0 .5rem;
                            }
                            &__title {
                                font-size: 1.1rem;
                                border-bottom: dashed 2px $faq-subcolor;
                                padding-bottom: .25rem !important;
                                margin-bottom: .5rem;
                            }
                            &__list {
                                display: -webkit-flex;
                                display: -ms-flexbox;
                                -ms-flex-wrap: wrap;
                                -webkit-flex-wrap: wrap;
                                @include tab {
                                    display: block;
                                }
                                a {
                                    color: black;
                                    width: calc(100% / 2 - 1rem);
                                    margin: .5rem;
                                    border-radius: 5px;
                                    box-shadow: $back-shadow;
                                    &:hover {
                                        color: #c9c9c9;
                                        opacity: .6;
                                    }
                                }
                                &__item {
                                    background-color: white;
                                    border-radius: 5px;
                                    padding: .5rem 1rem;
                                    span {
                                        padding-right: .75rem;
                                    }
                                    &__icon {
                                        min-width: 6%;
                                        max-width: 6%;
                                    }
                                }
                            }
                        }
                        &__detail {
                            margin: 2rem;
                            border-left: solid 5px $faq-maincolor;
                            padding: .5rem 0 .5rem 1rem;
                            &__title {
                                font-size: 1.1rem;
                            }
                        }
                    }
                    // キーワード・フリーワード
                    .faq-sound {
                        font-size: 1.3rem;
                        z-index: 1;
                        border-radius: 5px;
                        background: rgba(256, 256, 256, 0.7);
                        display: flex;
                        transform: translateY(0);
                        visibility: visible;
                        transition: .4s;
                        @include sp-wide-min {
                            -ms-flex-wrap: wrap;
                            -webkit-flex-wrap: wrap;
                        }
                        &.faq-sound__fixed {
                            position: fixed;
                            transition: .4s;
                        }
                        &.faq-sound__bottom {
                            visibility: hidden;
                            transition: .4s;
                        }
                        &__item {
                            background-color: white;
                            box-shadow: $back-shadow;
                            border: $faq-subcolor;
                            color: $faq-subcolor;
                            border: solid 1px $faq-subcolor;
                            border-radius: 5px;
                            padding: .5rem;
                            margin: .2rem;
                            width: 40px;
                            height: 40px;
                            display: -webkit-flex;
                            display: -ms-flexbox;
                            align-items: center;
                            text-align: center;
                            @include pc-md {
                                width: 35px;
                                height: 35px;
                            }
                        }
                        &__item.active {
                            background-color: $faq-subcolor;
                            color: white;
                            box-shadow: none;
                            border: none;
                        }
                        &__item.off {
                            background-color: #efefef;
                            color: gray;
                            box-shadow: none;
                            border: none;
                        }
                    }
                    .faq-search-word {
                        font-size: .9rem;
                        margin-top: .5rem;
                        color: gray;
                    }
                    h2 {
                        background-color: #F5F5EF;
                        padding: .5rem 1.5rem;
                        font-size: 1rem;
                        margin-top: 2rem;
                    }
                }
                .pnavi {
                    display: flex;
                    justify-content: center;
                    ul.page-numbers {
                        li {
                            margin: 0 0.2rem;
                            border: 1px solid $faq-maincolor;
                            a,
                            span {
                                border: none;
                            }
                            a {
                                color: $faq-maincolor;
                                &:hover {
                                    color: white !important;
                                    background-color: $faq-maincolor;
                                    opacity: .5;
                                }
                            }
                            &:hover {
                                opacity: .5;
                            }
                            span.page-numbers.current {
                                background-color: $faq-maincolor;
                            }
                            &:first-child>.page-numbers {
                                border-top-left-radius: 0;
                                border-bottom-left-radius: 0;
                            }
                            &:last-child>.page-numbers {
                                border-top-right-radius: 0;
                                border-bottom-right-radius: 0;
                            }
                            span.page-numbers.dots {
                                color: $faq-maincolor  !important;
                            }
                        }
                    }
                }
            }
        }
    }
}
