                }
                &__content {
                    box-shadow: $back-shadow;
                    &:active {
                        box-shadow: none;
                        transition-duration: .2s;
                    }
                    .acor-menu,
                    .acor-menu-child {
                        text-align: left;
                        font-size: 1.5rem;
                        p {
                            font-size: 1rem;
                            font-weight: bold;
