                    .acor-menu {
                        cursor: pointer;
                        padding: 0.5rem 3.5rem 0.5rem 1rem;
                        height: auto;
                        line-height: 2.2rem;
                        color: #38352b;
                        border: none;
                        background-color: white;
                        position: relative;
                        border-radius: 5px;
                        margin-bottom: .5rem;
                        @include sp-wide {
                            padding-left: 3.7rem;
                        }
                        &:after {
                            content: '';
                            border-right: 3px solid #918a70;
                            border-bottom: 3px solid #918a70;
                            content: "";
                            display: inline-block;
                            position: absolute;
                            top: 45%;
                            right: 30px;
                            width: 10px;
                            height: 10px;
                            transform: translateY(-50%) rotate(45deg);
                            transition: .3s;
                        }
                        &.opened {
                            box-shadow: none;
                            margin-bottom: 0;
                            border-radius: 5px 5px 0 0;
                            &:after {
                            transform: rotate(225deg);
                            }
                        }
                        p {
                            img {
                            @include sp-wide {
                                position: relative;
                            }
                            }
                            @include sp-wide {
                            text-indent: -2.7rem;
                            }
                        }
                    }
                    .acor-menu-child {
                        background-color: transparent;
                        padding: 0 0 0.75rem;
                        display: none;
                        background-color: white;
                        border-radius: 0 0 5px 5px;
                        margin-bottom: 0.5rem;
                        .answer {
                            display: -webkit-flex;
                            display: -ms-flexbox;
                            align-items: baseline;
                            margin: 0 auto;
                            p {
