.procedure_popup {
    position: fixed;
    width: 100%;
    height: 100%;
    z-index: 10000;
    display: none;
    top: 0;
    @include tab {
        display: block;
        top: 100%;
        left: 0;
        transition: .5s;
        opacity: 1;
    }
    .document_popup_tit {
        width: 100%;
        border-bottom: solid 1px $procedure-main_color;
        padding: .25rem .5rem;
        margin-bottom: .5rem;
        p {
            max-width: calc(100% - 100px);
            font-weight: bold;
        }
    }
    .document_detail {
        padding: 0 .5rem;
        &__txt {
            ul {
                padding-left: 1.3rem;
            }
        }
        &__note {
            &__content {
                background-color: #FAF8F5;
                border-radius: 5px;
                padding: .5rem 1rem;
                margin-bottom: .5rem;
                &:last-child {
                    margin-bottom: 0;
                }
                .content_about {
                    ul {
                        padding-left: 1.3rem;
                    }
                }
            }
        }
        .starter_content {
            .starter_item {
                margin-bottom: 1.5rem;
                &__tit {
                    background-color: $procedure-main_color;
                    padding: .1rem .75rem;
                    p {
                        color: white;
                        font-weight: bold;
                    }
                }
                &__about {
                    padding: .5rem .75rem;
                    &__content {
                        .item_txt {
                            text-align: end;
                        }
                    }
                }
            }
        }
    }
    &__bg {
        background-color: rgba(30,30,30,.65);
        height: 100%;
        width: 100%;
        @include tab {
            background-color: transparent;
        }
    }
    &__close {
        width: 100px;
        cursor: pointer;
        position: absolute;
        right: 1rem;
        @include tab {
            position: static;
        }
        & > div {
            color: #DB5EAE;
            font-weight: bold;
            text-align: center;
            font-size: .8rem;
            line-height: 1.9;
            border: 1px solid #DB5EAE;
        }
    }
    &::after {
        content: "";
        width: 75%;
        height: 2rem;
        left: 50%;
        transform: translateX(-50%);
        bottom: 12.5%;
        border-radius: 0 0 6px 6px;
